$ErrorActionPreference = 'Stop'
$compiler = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
if (-not (Test-Path -LiteralPath $compiler)) { throw '需要 Windows 的 .NET Framework 4.x 编译器。' }
& $compiler /nologo /target:winexe /platform:x64 /optimize+ /codepage:65001 /out:"$PSScriptRoot\OfficeBuddyStudio.exe" /win32manifest:"$PSScriptRoot\application.manifest" /resource:"$PSScriptRoot\assets\mint-cat.png,OfficeBuddy.cat.png" /resource:"$PSScriptRoot\assets\mint-cat-rig.png,OfficeBuddy.rig.png" /resource:"$PSScriptRoot\assets\mint-cat-water.png,OfficeBuddy.water.png" /resource:"$PSScriptRoot\assets\apricot-rabbit.png,OfficeBuddy.rabbit.png" /resource:"$PSScriptRoot\assets\moon-cat.png,OfficeBuddy.night.png" /resource:"$PSScriptRoot\assets\apricot-rabbit-rig.png,OfficeBuddy.rabbit-rig.png" /resource:"$PSScriptRoot\assets\moon-cat-rig.png,OfficeBuddy.night-rig.png" /reference:System.Windows.Forms.dll /reference:System.Drawing.dll /reference:System.Runtime.Serialization.dll /reference:System.Core.dll "$PSScriptRoot\OfficeBuddy.cs" "$PSScriptRoot\SpriteMotion.cs" "$PSScriptRoot\PixelEye.cs" "$PSScriptRoot\PixelDecor.cs" "$PSScriptRoot\WorkFeatures.cs" "$PSScriptRoot\BuddyFeatures.cs" "$PSScriptRoot\SettingsForm.cs" "$PSScriptRoot\FeatureChecks.cs"
if ($LASTEXITCODE -ne 0) { throw '编译失败。' }
Write-Output '已生成 OfficeBuddyStudio.exe'
